// `@shrutibalasa/tailwind-grid-auto-fit` ships no type declarations. Declare it
// so the ESM import in tailwind.config.ts type-checks — this is what lets us use
// `import` instead of `require()` (satisfying @typescript-eslint/no-require-imports
// without an inline disable).
declare module "@shrutibalasa/tailwind-grid-auto-fit";
